$('motor-button').onclick=()=>setMode('motor');$('row-button').onclick=()=>setMode('row');$('cruise-button').onclick=()=>{if(state.mode==='row')setMode('motor');state.cruise=!state.cruise;updateUI();notice(state.cruise?'A gentle cruise. Steer any time to take over.':'You have the helm.');};$('camera-button').onclick=cycleCamera;$('sound-button').onclick=toggleAudio;$('hide-button').onclick=hideUI;$('show-button').onclick=hideUI;$('time-button').onclick=changeTime;$('reset-button').onclick=reset;
